import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, timer } from 'rxjs';
import { retry, retryWhen, delay, take, concat } from 'rxjs/operators';
import { Router } from '@angular/router';
import { HealthService } from './health.service';

@Injectable({
  providedIn: 'root'
})
export class AuthService {

  private apiUrl = 'https://backend-domain.com/api/health';

  constructor(private http: HttpClient, private healthService: HealthService, private router: Router) { }

  getToken(): string | null {
    return localStorage.getItem('jwt_token');
  }

  setToken(token: string): void {
    localStorage.setItem('jwt_token', token);
  }

  removeToken(): void {
    localStorage.removeItem('jwt_token');
  }


  isAuthenticated(): boolean {
    const token = this.getToken();
    if (!token) {
      return false;
    }

    try {
      const payload = this.decodeTokenPayload(token);
      const currentTime = Math.floor(Date.now() / 1000);

      return payload.exp > currentTime;
    } catch (error) {
      return false;
    }
  }

  getUserEmail(): string | null {
    try {
      const token = this.getToken();
      if (!token) {
        return null;
      }

      const payload = this.decodeTokenPayload(token);
      return payload.sub || payload.email || null;
    } catch (error) {
      console.error('Error extracting email from token:', error);
      return null;
    }
  }

  private decodeTokenPayload(token: string): any {
    const payload = token.split('.')[1];
    return JSON.parse(atob(payload));
  }




  initiateClientaHandshake(): void {
    this.http.get(`${this.apiUrl}/validate-clienta`).subscribe({
      next: (response: any) => {
        if (response?.valid && response?.token) {
          this.setToken(response.token);
          console.log('Clienta handshake success for user:', response.user);
        } else {
          this.handleInvalidToken();
        }
      },
      error: (error) => {
        console.error('Clienta handshake failed:', error);
        this.handleTokenValidationError(error);
      }
    });
  }

  ensureValidSession(): void {
    const existing = this.getToken();
    if (existing) {
      this.validateTokenWithBackend(existing);
    } else {
      this.initiateClientaHandshake();
    }
  }

  validateTokenWithBackend(token: string): void {
    const validationMethod = this.validateTokenViaBearer(token);

    validationMethod.pipe(
      retryWhen(errors => 
        errors.pipe(
          delay(2000), // Wait 2 seconds between retries
          take(3) // Retry up to 3 times
        )
      )
    ).subscribe({
      next: (response) => {
        if (response.valid) {
          this.setToken(token);
          console.log('Token validated successfully for user:', response.user);
        } else {
          this.handleInvalidToken();
        }
      },
      error: (error) => {
        console.error('Token validation failed after retries:', error);
        this.handleTokenValidationError(error);
      }
    });
  }


  validateTokenViaBearer(token: string): Observable<any> {
    return this.http.get(`${this.apiUrl}/validate-token`, {
      headers: { 'Authorization': `Bearer ${token}` }
    });
  }

  handleInvalidToken(): void {
    console.error('Invalid or expired token. Please try again.');
    this.removeToken();
    this.router.navigate(['/redirect']);
  }

  private handleTokenValidationError(error: any): void {
    // Check if it's a network/server error vs authentication error
    if (this.isNetworkError(error)) {
      console.warn('Backend unavailable, keeping session for retry');
      this.handleNetworkError();
    } else if (this.isAuthenticationError(error)) {
      console.error('Authentication failed, logging out user');
      this.handleInvalidToken();
    } else {
      console.error('Unknown error during token validation:', error);
      this.handleInvalidToken();
    }
  }

  private isNetworkError(error: any): boolean {
    // Network errors: 0 (no response), 5xx (server errors), timeout
    return error.status === 0 || 
           (error.status >= 500 && error.status < 600) ||
           error.message?.includes('timeout') ||
           error.message?.includes('Network Error') ||
           error.message?.includes('ERR_NETWORK');
  }

  private isAuthenticationError(error: any): boolean {
    // Authentication errors: 401 (Unauthorized), 403 (Forbidden)
    return error.status === 401 || error.status === 403;
  }

  private handleNetworkError(): void {
    // Keep the token and show a user-friendly message
    // You could emit an event or show a toast notification here
    console.warn('Backend is temporarily unavailable. Your session will be preserved.');
    // Optionally show a notification to the user
    this.showNetworkErrorMessage();
  }

  private showNetworkErrorMessage(): void {
    // This could be implemented with a toast service or notification
    // For now, we'll just log it - you can integrate with your UI framework
    console.warn('Network error: Backend is temporarily unavailable');
  }
}
